// Builds the code the applications run from the design system's standards (platform/standards/*.json). Run by build-app.js.
//   platform/standards/layout.json  →  platform/providers/pageLayouts.js   which layout each kind of page gets
//                                   →  platform/system/layout-modes.css     how each layout mode is drawn
// The standard is the design system's definition: edit the JSON, never the generated files (check-system's rule
// "generated" rejects a hand edit). With { check: true } nothing is written; the result lists the files that differ.
const fs = require('fs');
const path = require('path');

const MODES = ['fluid', 'contained', 'hybrid', 'multi-pane', 'focus'];

module.exports = function buildStandards(root, opts) {
  const check = !!(opts && opts.check);
  const P = path.join(root, 'platform');
  const src = path.join(P, 'standards', 'layout.json');
  const std = JSON.parse(fs.readFileSync(src, 'utf8'));
  const refCss = fs.readFileSync(path.join(P, 'system', 'tokens', 'reference.css'), 'utf8');
  const errors = [];
  // a width is a token reference, written as the token files write them: {plx-ref.content-max-960px}
  const token = (v, where) => {
    const m = /^\{(plx-(?:ref|sys))\.([a-z0-9-]+)\}$/.exec(String(v || ''));
    if (!m) { errors.push(where + ': "' + v + '" is not a token reference like {plx-ref.content-max-960px}'); return 'var(--missing)'; }
    const name = '--' + m[1] + '-' + m[2];
    if (m[1] === 'plx-ref' && refCss.indexOf(name + ':') < 0) errors.push(where + ': ' + name + ' is not a token');
    return 'var(' + name + ')';
  };
  Object.keys(std.modes || {}).forEach((m) => { if (MODES.indexOf(m) < 0) errors.push('modes: "' + m + '" is not a layout mode (' + MODES.join(', ') + ')'); });
  MODES.forEach((m) => { if (!std.modes || !std.modes[m]) errors.push('modes: "' + m + '" is missing'); });
  Object.keys(std.pages || {}).forEach((k) => { if (!std.modes || !std.modes[std.pages[k].mode]) errors.push('pages.' + k + ': mode "' + std.pages[k].mode + '" is not defined'); });
  if (!std.pages || !std.pages[std.default]) errors.push('default: "' + std.default + '" is not a kind of page');

  // ---- providers/pageLayouts.js: the page kinds, for AppShell
  const pages = {}; Object.keys(std.pages).forEach((k) => { pages[k] = { layout: std.pages[k].mode, use: std.pages[k].use }; });
  const HEAD = ["/* Plenix · Page layouts (platform/providers/pageLayouts.js)", "   GENERATED by build-standards.js from platform/standards/layout.json (the design system's layout standard): edit the", "   JSON, never this file.", "   Summary: Which layout each kind of page gets. An application says what a page is; the standard decides how it is laid out.", "   Usage:", "     <AppShell page=\"settings\">…</AppShell>    (or a pattern that is that kind of page, such as SettingsLayout)", "     pageLayout(\"settings\")                   // \"contained\"", "   Props:", "     PAGE_LAYOUTS: { <kind>: { layout, use } } from the standard", "     DEFAULT_PAGE: the kind of page when none is given", "     pageLayout(kind): the layout mode of a kind of page (the default kind's for an unknown kind)", "*/"];
  const js = HEAD.join(String.fromCharCode(10)) + String.fromCharCode(10)
    + 'export const PAGE_LAYOUTS = ' + JSON.stringify(pages, null, 2).replace(/"([a-z]+)":/g, '$1:') + ';\n\n'
    + 'export const DEFAULT_PAGE = ' + JSON.stringify(std.default) + ';\n\n'
    + 'export function pageLayout(kind) {\n  return (PAGE_LAYOUTS[kind] || PAGE_LAYOUTS[DEFAULT_PAGE]).layout;\n}\n';

  // ---- system/layout-modes.css: how each mode is drawn
  const S = (mode) => '.plx-app-shell[data-plx-layout="' + mode + '"]';
  const PAD = 'var(--plx-sys-space-layout-md)';   // PageContent's own inline padding: the least a contained column keeps
  const css = ['/* GENERATED by build-standards.js from platform/standards/layout.json (the design system\'s layout standard). Edit the',
    '   JSON, never this file. Plenix · Layout modes (platform/system/layout-modes.css): how each mode is drawn on an AppShell',
    '   page (data-plx-layout on the shell, from the page\'s kind). */'];
  const M = std.modes;
  css.push('/* fluid: ' + M.fluid.description + ' */');
  if (M.contained) {
    const w = token(M.contained.maxWidth, 'modes.contained.maxWidth'), sel = S('contained') + ' :is(.plx-page-content,.plx-settings__content)';
    css.push('/* contained: ' + M.contained.description + ' Aligned ' + (M.contained.align || 'center') + '. */');
    if ((M.contained.align || 'center') === 'center') {
      const side = 'max(' + PAD + ', calc((100% - ' + w + ') / 2))';
      css.push(sel + '{padding-inline-end:' + side + ';padding-inline-start:' + side + ';}');
    } else if (M.contained.align === 'start') {
      css.push(sel + '{padding-inline-end:max(' + PAD + ', calc(100% - ' + w + ' - ' + PAD + '));padding-inline-start:' + PAD + ';}');
    } else errors.push('modes.contained.align: "' + M.contained.align + '" is not center or start');
  }
  if (M.hybrid) {
    css.push('/* hybrid: ' + M.hybrid.description + ' */');
    if (M.hybrid.proseMaxWidth) css.push(S('hybrid') + ' .plx-page-content>p{max-inline-size:' + token(M.hybrid.proseMaxWidth, 'modes.hybrid.proseMaxWidth') + ';}');
    if (M.hybrid.formMaxWidth) css.push(S('hybrid') + ' .plx-page-content>:is(form,.plx-fieldset,.plx-field){max-inline-size:' + token(M.hybrid.formMaxWidth, 'modes.hybrid.formMaxWidth') + ';}');
  }
  if (M['multi-pane']) {
    css.push('/* multi-pane: ' + M['multi-pane'].description + ' */');
    if (M['multi-pane'].panesScroll) {
      css.push(S('multi-pane') + ' .plx-app-shell__main{overflow-x:hidden;overflow-y:hidden;}');
      css.push(S('multi-pane') + ' .plx-app-shell__main>*{min-block-size:0;overflow-y:auto;}');
    }
  }
  if (M.focus) {
    css.push('/* focus: ' + M.focus.description + ' */');
    const AREA = { navigation: '.plx-app-shell__body>:not(.plx-app-shell__main):has(~.plx-app-shell__main)', inspector: '.plx-app-shell__main~*' };
    const hide = (M.focus.hide || []).map((a) => { if (!AREA[a]) errors.push('modes.focus.hide: "' + a + '" is not navigation or inspector'); return AREA[a]; }).filter(Boolean);
    if (hide.length) css.push(hide.map((a) => S('focus') + ' ' + a).join(',') + '{display:none;}');
  }
  if (errors.length) throw new Error('platform/standards/layout.json:\n  ' + errors.join('\n  '));

  // ---- the themes (platform/standards/themes.json): the list the apps offer, and the stylesheet that loads every theme
  // (each theme's own stylesheet is made by build-tokens.js from its token files)
  const themes = JSON.parse(fs.readFileSync(path.join(P, 'standards', 'themes.json'), 'utf8'));
  const tnames = Object.keys(themes.themes || {}).sort((a, b) => (a === themes.default ? -1 : b === themes.default ? 1 : 0));
  if (!themes.themes || !themes.themes[themes.default]) errors.push('themes.json: the default theme "' + themes.default + '" is not defined');
  tnames.forEach((n) => { if (!/^[a-z][a-z0-9-]*$/.test(n)) errors.push('themes.json: "' + n + '" is not a theme name (lowercase letters, digits, hyphens)'); });
  if (errors.length) throw new Error('platform/standards:\n  ' + errors.join('\n  '));
  const list = tnames.map((n) => ({ name: n, label: themes.themes[n].label || n, description: themes.themes[n].description || '' }));
  const tjs = ['/* Plenix · Themes (platform/providers/themes.js)',
    '   GENERATED by build-standards.js from platform/standards/themes.json (the design system\'s themes): edit the JSON, never',
    '   this file.',
    '   Summary: The themes a page can use. The default theme is the current Plenix look; more are added in the design system.',
    '   Usage:',
    '     const { theme, setTheme, themes } = useTheme();   // providers/ThemeProvider.jsx',
    '     PlenixWorkspace.setTheme("default")               // providers/theme-boot.js, before React',
    '   Props:',
    '     THEMES: [{ name, label, description }], the default theme first',
    '     DEFAULT_THEME: the theme a page has when none is chosen',
    '*/',
    'export const THEMES = ' + JSON.stringify(list, null, 2).replace(/"([a-z]+)":/g, '$1:') + ';',
    '',
    'export const DEFAULT_THEME = ' + JSON.stringify(themes.default) + ';',
    ''].join('\n');
  const tcss = ['/* GENERATED by build-standards.js from platform/standards/themes.json (the design system\'s themes). Edit the JSON, never',
    '   this file. Plenix · Themes (platform/system/themes/index.css): every theme\'s stylesheet, the default theme first. */']
    .concat(tnames.map((n) => '@import url("' + n + '.css");')).join('\n') + '\n';

  const out = { 'platform/providers/pageLayouts.js': js, 'platform/system/layout-modes.css': css.join('\n') + '\n',
    'platform/providers/themes.js': tjs, 'platform/system/themes/index.css': tcss };
  const stale = Object.keys(out).filter((f) => { const full = path.join(root, f); return !fs.existsSync(full) || fs.readFileSync(full, 'utf8') !== out[f]; });
  if (!check) stale.forEach((f) => fs.writeFileSync(path.join(root, f), out[f]));
  return { files: Object.keys(out), stale, pages: Object.keys(std.pages).length };
};

if (require.main === module) {
  const r = module.exports(__dirname);
  console.log('Built ' + r.files.join(', ') + ' from platform/standards/layout.json (' + r.pages + ' kinds of page)');
}
